60	function loadFromStorage(key, fallback) {
61	  if (typeof window === 'undefined') return fallback;
62	  try {
63	    const item = localStorage.getItem(`techgy_${key}`);
64	    return item ? JSON.parse(item) : fallback;
65	  } catch {
66	    return fallback;
67	  }
68	}
