182	      const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
183	      setLeads(prevLeads => {
184	        let hasChanged = false;
185	        const updated = prevLeads.map(lead => {
186	          if (!lead.nextFollowup) return lead;
187	
188	          let nextFollowup = lead.nextFollowup;
189	          // Keep default designated 'Today' mock leads anchored to the current calendar day
190	          if (lead.id === 'LD-201' && !lead.customFollowupSet) {
191	            nextFollowup = `${todayStr} 15:30`;
192	          } else if (lead.id === 'LD-203' && !lead.customFollowupSet) {
193	            nextFollowup = `${todayStr} 16:30`;
194	          } else if (lead.id === 'LD-206' && !lead.customFollowupSet) {
195	            nextFollowup = `${todayStr} 17:00`;
196	          } else if (lead.id === 'LD-207' && !lead.customFollowupSet) {
197	            nextFollowup = `${todayStr} 18:00`;
198	          }
199	
200	          const followupTs = new Date(nextFollowup.replace(' ', 'T')).getTime();
201	          if (isNaN(followupTs)) return lead;
202	
203	          const isToday = nextFollowup.startsWith(todayStr);
204	          const isOverdue = !isToday && followupTs < now.getTime() && lead.status !== 'Converted' && lead.status !== 'Lost';
205	
206	          if (lead.isOverdue !== isOverdue || lead.dueToday !== isToday || lead.nextFollowup !== nextFollowup) {
207	            hasChanged = true;
208	            return { ...lead, nextFollowup, isOverdue, dueToday: isToday };
209	          }
210	          return lead;
211	        });
212	        return hasChanged ? updated : prevLeads;
213	      });
214	    };
215	
