  background: #F8F9FA;
  border: 1px solid #E2E8F0;
  border-radius: var(--radius);
  font-size: 15px;
  color: #0F1A34;
  outline: none;
  transition: border-color var(--dur-base) ease, box-shadow var(--dur-base) ease, background-color var(--dur-base) ease;
}

.auth-input.has-action {
  padding-right: 46px;
}

.auth-input::placeholder {
  color: #A3B1C6;
}

.auth-input:hover {
  border-color: #CBD5E1;
}

.auth-input:focus {
  background: #FFFFFF;
  border-color: #0022FF;
  box-shadow: 0 0 0 3px rgba(0, 34, 255, 0.12);
}

.auth-input-action {
  position: absolute;
  right: 7px;
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: #8A9BB4;
  cursor: pointer;
  transition: color var(--dur-base) ease, background-color var(--dur-base) ease;
}

.auth-input-action:hover {
  color: #0022FF;
  background: #EBF0FF;
}

.auth-row-end {
  display: flex;
  justify-content: flex-end;
  margin-top: -6px;
}

.auth-row-center {
  display: flex;
  justify-content: center;
  margin-top: 16px;
}

/* Text link with an underline that draws in on hover */
.auth-link {
  position: relative;
  padding: 2px 0;
  background: none;
  border: none;
  font-size: 13px;
  font-weight: 600;
  color: #0022FF;
  cursor: pointer;
}

.auth-link::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: right;
  transition: transform var(--dur-slow) var(--ease-out);
}

.auth-link:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.auth-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 50px;
  margin-top: 6px;
  background: #0022FF;
  border: none;
  border-radius: var(--radius-pill);
  color: #FFFFFF;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 18px -6px rgba(0, 34, 255, 0.55);
  transition:
    background-color var(--dur-base) ease,
    box-shadow var(--dur-base) ease,
    transform var(--dur-fast) var(--ease-out);
}

.auth-submit:hover:not(:disabled) {
  background: #001AD4;
  box-shadow: 0 10px 24px -8px rgba(0, 34, 255, 0.6);
  transform: translateY(-1px);
}

.auth-submit:active:not(:disabled) {
  transform: translateY(0) scale(0.98);
  transition-duration: 60ms;
}

.auth-submit:disabled {
  opacity: 0.85;
  cursor: progress;
}

.auth-submit-arrow {
  transition: transform var(--dur-base) var(--ease-out);
}

.auth-submit:hover:not(:disabled) .auth-submit-arrow {
  transform: translateX(3px);
}

@keyframes authSpin {
  to { transform: rotate(360deg); }
}

.auth-spin {
  animation: authSpin 0.8s linear infinite;
}

.auth-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 24px;
  padding: 6px 12px 6px 8px;
  background: none;
  border: none;
  font-size: 13px;
  font-weight: 600;
  color: #556987;
  cursor: pointer;
  transition: color var(--dur-base) ease, background-color var(--dur-base) ease;
}

.auth-back:hover {
  color: #0022FF;
  background: #EBF0FF;
}

.auth-back svg {
  transition: transform var(--dur-base) var(--ease-out);
}

.auth-back:hover svg {
  transform: translateX(-3px);
}

.auth-success-badge {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  background: #EBF0FF;
  border-radius: var(--radius);
  color: #0022FF;
}

.auth-secure-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid #EEF1F6;
  font-size: 12px;
  color: #6B7C93;
  text-align: center;
}

.auth-secure-note svg {
  flex-shrink: 0;
  color: #0022FF;
}

.auth-footer {
  font-size: 12px;
  color: #8A9BB4;
}

/* Brand panel */
.auth-showcase {
  position: relative;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  margin: 12px;
  padding: 56px;
  border-radius: var(--radius);
  color: #FFFFFF;
  background:
    radial-gradient(120% 80% at 100% 0%, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0) 55%),
    linear-gradient(160deg, #0022FF 0%, #001AD4 55%, #0F1A34 130%);
}

.auth-showcase-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.07) 1px, transparent 1px);
  background-size: 48px 48px;
  -webkit-mask-image: radial-gradient(ellipse at 70% 20%, #000 0%, transparent 70%);
  mask-image: radial-gradient(ellipse at 70% 20%, #000 0%, transparent 70%);
}

@keyframes authMarkSpin {
  to { transform: rotate(360deg); }
}

/* Oversized logo mark, tinted white, turning very slowly */
.auth-showcase-mark {
  position: absolute;
  top: -120px;
  right: -160px;
  width: 620px;
  height: 620px;
  opacity: 0.1;
  filter: brightness(0) invert(1);
  pointer-events: none;
  animation: authMarkSpin 120s linear infinite;
}

.auth-showcase-content {
  position: relative;
  z-index: 1;
  max-width: 460px;
}

.auth-showcase-icon {
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 28px;
  background: #FFFFFF;
  border-radius: var(--radius);
  box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.35);
}

.auth-showcase-icon img {
  width: 30px;
  height: 30px;
  object-fit: contain;
}

.auth-showcase-title {
  margin: 0 0 14px;
  font-size: 34px;
  line-height: 42px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.auth-showcase-text {
  margin: 0 0 32px;
  font-size: 15px;
  line-height: 24px;
  color: rgba(255, 255, 255, 0.78);
}

.auth-features {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.auth-feature {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: var(--radius);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  transition: background-color var(--dur-base) ease, border-color var(--dur-base) ease;
}

.auth-feature:hover {
  background: rgba(255, 255, 255, 0.13);
  border-color: rgba(255, 255, 255, 0.24);
}

.auth-feature-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.14);
  border-radius: var(--radius);
}

.auth-feature-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 13px;
  line-height: 19px;
  color: rgba(255, 255, 255, 0.75);
}

.auth-feature-body strong {
  font-size: 14px;
  font-weight: 600;
  color: #FFFFFF;
}

@media (max-width: 1100px) {
  .auth-form-panel {
    padding: 32px 40px 24px;
  }

  .auth-showcase {
    padding: 40px;
  }

  .auth-showcase-title {
    font-size: 28px;
    line-height: 36px;
  }
}

@media (max-width: 860px) {
  .auth-page {
    grid-template-columns: minmax(0, 1fr);
  }

  .auth-showcase {
    display: none;
  }

  .auth-form-panel {
    padding: 24px 16px 20px;
  }

  .auth-form-wrap {
    padding: 32px 0;
  }

  .auth-title {
    font-size: 26px;
    line-height: 34px;
  }
}

