"""Tiny JSX opening-tag scanner: yields (tag, start, end, attrs_text) for <tag ...> openings."""
import re
def iter_tags(s, names):
    pat = re.compile(r'<(' + '|'.join(names) + r')(?=[\s>/])')
    for m in pat.finditer(s):
        i = m.end(); depth = 0; quote = None
        while i < len(s):
            c = s[i]
            if quote:
                if c == quote and s[i-1] != '\\': quote = None
            elif c in '"\'`' and depth > 0: quote = c
            elif c == '"' and depth == 0: quote = c
            elif c == '{': depth += 1
            elif c == '}': depth -= 1
            elif c == '>' and depth == 0: break
            i += 1
        yield m.group(1), m.start(), i, s[m.end():i]
