const str = (v) => (typeof v === 'string' ? v.trim() : v == null ? '' : String(v).trim());

export const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(str(v));

// 7–15 digits, optionally with + ( ) - . and spaces
export const isPhone = (v) => {
  const s = str(v);
  return /^\+?[\d\s().-]+$/.test(s) && s.replace(/\D/g, '').length >= 7 && s.replace(/\D/g, '').length <= 15;
};

export const isUrl = (v) => {
  try {
    const url = new URL(/^https?:\/\//i.test(str(v)) ? str(v) : `https://${str(v)}`);
    return url.hostname.includes('.');
  } catch {
    return false;
  }
};

export const required = (label) => (v) => (str(v) ? '' : `${label} is required.`);
export const minLength = (label, n) => (v) => (!str(v) || str(v).length >= n ? '' : `${label} must be at least ${n} characters.`);
export const maxLength = (label, n) => (v) => (str(v).length <= n ? '' : `${label} must be ${n} characters or fewer.`);
export const email = (label = 'Email') => (v) => (!str(v) || isEmail(v) ? '' : `Enter a valid ${label.toLowerCase()} address.`);
export const phone = (label = 'Phone number') => (v) => (!str(v) || isPhone(v) ? '' : `Enter a valid ${label.toLowerCase()} (7–15 digits).`);
export const url = (label = 'Website') => (v) => (!str(v) || isUrl(v) ? '' : `Enter a valid ${label.toLowerCase()} URL.`);
export const notInPast = (label) => (v) => {
  const s = str(v).slice(0, 10);
  if (!s) return '';
  const today = new Date();
  const todayIso = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
  return s >= todayIso ? '' : `${label} can’t be in the past.`;
};

/** Run `{ field: [validators] }` against `values`; returns `{ field: message }` for failures. */
export function validate(values, rules) {
  const errors = {};
  for (const [field, validators] of Object.entries(rules)) {
    for (const check of validators) {
      const message = check(values[field], values);
      if (message) {
        errors[field] = message;
        break;
      }
    }
  }
  return errors;
}

const norm = (v) => str(v).toLowerCase();
const digits = (v) => str(v).replace(/\D/g, '');

/** Existing lead that shares an email or phone number with `candidate`, if any. */
export function findDuplicateLead(leads, candidate) {
  const mail = norm(candidate.email);
  const tel = digits(candidate.phone);
  return leads.find(l =>
    (mail && norm(l.emailId) === mail) ||
    (tel.length >= 7 && digits(l.phoneNumber).endsWith(tel.slice(-10)))
  ) || null;
}

