  else if (kind === 'click') { res = await evaluate(`window.__click(${JSON.stringify(arg)})`); await sleep(extra || 700); }
  else if (kind === 'type') { res = await evaluate(`(() => { const el = document.querySelector(${JSON.stringify(arg)}); if (!el) return 'NOT FOUND'; el.focus(); const set = Object.getOwnPropertyDescriptor(el.__proto__, 'value').set; set.call(el, ${JSON.stringify(extra)}); el.dispatchEvent(new Event('input', { bubbles: true })); return 'typed'; })()`); await sleep(200); }
  else if (kind === 'wait') { await sleep(arg); }
