import re, sys
DEAD = set('banner-text card-select-filter chart-container cta dashboard-banner logout-header-btn menu-index prob-number-input prob-percent-symbol prob-scale-bound probability-badge-input-wrap probability-range-slider probability-slider-wrapper revenue-chart-container selected-row sh-segmented-btn sh-segmented-group sidebar-footer table-checkbox table-cta-bar table-cta-btn table-cta-divider table-responsive table-scroll-container td-checkbox th-checkbox user-info user-name user-profile user-role'.split())
removed = {'rules': 0, 'selectors': 0}

def match_brace(s, i):
    depth = 0
    for k in range(i, len(s)):
        if s[k] == '{': depth += 1
        elif s[k] == '}':
            depth -= 1
            if depth == 0: return k
    raise ValueError('unbalanced')

def is_dead(sel):
    return any(c in DEAD for c in re.findall(r'\.([a-zA-Z][\w-]*)', sel))

def process(s):
    out = []; i = 0
    while i < len(s):
        j = s.find('{', i)
        if j == -1: out.append(s[i:]); break
        # prelude = text since last rule end, but keep leading comments/whitespace
        pre = s[i:j]
        k = match_brace(s, j)
        body = s[j + 1:k]
        m = re.match(r'(\s*(?:/\*.*?\*/\s*)*)(.*)$', pre, re.S)
        lead, prelude = m.group(1), m.group(2)
        if prelude.strip().startswith('@media') or prelude.strip().startswith('@supports'):
            inner = process(body)
            if inner.strip():
                out.append(lead + prelude + '{' + inner + '}')
            else:
                removed['rules'] += 1
        elif prelude.strip().startswith('@'):
            out.append(s[i:k + 1])
        else:
            sels = [x for x in prelude.split(',')]
            keep = [x for x in sels if not is_dead(x)]
            if not keep:
                removed['rules'] += 1
                # drop the rule and any comment directly attached to it
                out.append('\n' if lead.count('\n') else '')
            else:
                if len(keep) != len(sels):
                    removed['selectors'] += len(sels) - len(keep)
                    keep[0] = keep[0].lstrip()
                    prelude = ',\n'.join(x.strip() for x in keep) + ' '
                    out.append(lead + prelude + '{' + body + '}')
                else:
                    out.append(s[i:k + 1])
        i = k + 1
    return ''.join(out)

p = sys.argv[1]
src = open(p).read()
res = process(src)
res = re.sub(r'\n{3,}', '\n\n', res)
open(p, 'w').write(res)
